import pandas as pd,numpy as np
def ED(d,X,R=0.0):
    V=d.voltage_pu.values*np.exp(1j*d.bus_angle_rad.values)
    S=d.active_power_pu.values+1j*d.reactive_power_pu.values
    I=np.conj(S/V)
    E=V+(R+1j*X)*I
    return np.abs(E),np.angle(E)
