def unpack(p,nr,nc):
    poles=[('r',np.exp(p[i])) for i in range(nr)]
    for j in range(nc):
        poles.append(('c',np.exp(p[nr+2*j]),1/(1+np.exp(-p[nr+2*j+1]))))
    return poles
def build(f,poles):
    V,th,Vs=IN[f]
