import pandas as pd,numpy as np,glob
from scipy.signal import lfilter
files=sorted(glob.glob('train/*.csv'));vf=sorted(glob.glob('val/*.csv'))
D={f:pd.read_csv(f) for f in files+vf}
dt=0.001;WB=377
def lp(x,tau):
    a=dt/(tau+dt);return lfilter([a],[1,-(1-a)],x-x[0])+x[0]
def Ed(d,Z):
    Vc=d.voltage_pu.values*np.exp(1j*d.bus_angle_rad.values);S=d.active_power_pu.values+1j*d.reactive_power_pu.values
    I=np.conj(S/Vc);E=Vc+Z*I
    return np.abs(E),np.unwrap(np.angle(E))
fl=[f for f in files if 'fault' not in f]
best=[]
for R in [0.9,1.0,1.1,1.2,1.3]:
