            d=D[f];E,dl=Ed(d,R+1j*X)
            w=np.gradient(dl,dt)/WB; w=lp(w,0.005)
            P=d.active_power_pu.values-d.active_power_pu.values[0]
            F=np.c_[P,lp(P,0.01),lp(P,0.03),lp(P,0.1)]
            c=np.linalg.lstsq(F,w,rcond=None)[0];r=w-F@c
            tot+=np.sum(r[100:]**2);tv+=np.sum(w[100:]**2)
        best.append((tot/tv,R,X,np.round(c,4)))
best.sort(key=lambda z:z[0]);
